// INDEPENDENT COUNTRY CONFLICT COMPARISON

async function initializeCountryComparison() {
    const countryA = document.getElementById("compareCountryA");
    const countryB = document.getElementById("compareCountryB");

    if (!countryA || !countryB) return;

    try {
        const response = await fetch("../data/dashboard_data.json");

        if (!response.ok) {
            throw new Error("Unable to load comparison data");
        }

        const data = await response.json();

        const countries = [
            ...new Set(
                data.country_annual_events.map(item => item.country)
            )
        ].sort();

        countries.forEach(country => {
            countryA.add(new Option(country, country));
            countryB.add(new Option(country, country));
        });

        function updateComparison() {
            const selectedA = countryA.value;
            const selectedB = countryB.value;

            if (!selectedA || !selectedB) return;

            renderHistoricalComparison(data, selectedA, selectedB);
        }

        countryA.addEventListener("change", updateComparison);
        countryB.addEventListener("change", updateComparison);

        console.log("Independent country comparison initialized");

    } catch (error) {
        console.error("Country comparison initialization failed:", error);
    }
}

initializeCountryComparison();